import { z } from 'zod'

// No manual "announcement": delivery and calendar notices will be generated by the system later.
export const BANNER_TYPES = ['promotion', 'warning', 'maintenance', 'informational'] as const
export const BANNER_AUDIENCES = ['all_users', 'prepaid', 'credit', 'subscribers'] as const
export const BANNER_CTA_TYPES = ['none', 'product', 'category', 'offers'] as const
export const BANNER_STATUSES = ['active', 'inactive'] as const

/** `2026-10-10` that is also a real calendar day (so 2026-02-30 is refused). */
function isRealDate(value: string): boolean {
  const date = new Date(`${value}T00:00:00Z`)
  return !Number.isNaN(date.getTime()) && date.toISOString().slice(0, 10) === value
}
const dateOrNull = z.string().trim().regex(/^\d{4}-\d{2}-\d{2}$/, 'Use the format YYYY-MM-DD.').refine(isRealDate, 'That date does not exist.').nullable().default(null)
const text = (max: number) => z.string().trim().max(max, `Keep this under ${max} characters.`)

export const bannerInputSchema = z.object({
  type: z.enum(BANNER_TYPES).default('promotion'),
  audience: z.enum(BANNER_AUDIENCES).default('all_users'),
  titleEn: text(80).min(1, 'Enter a headline.'),
  titleGu: text(80).default(''),
  messageEn: text(160).default(''),
  messageGu: text(160).default(''),
  /** A short optional tag on the card, such as "SEASONAL OFFER". Empty shows nothing. */
  labelEn: text(24).default(''),
  labelGu: text(24).default(''),
  /** A finished upload from `/admin/media`; null means no picture. */
  imageAssetId: z.uuid('That is not a valid picture id.').nullable().default(null),
  ctaType: z.enum(BANNER_CTA_TYPES).default('none'),
  ctaTarget: text(64).default(''),
  startDate: dateOrNull,
  endDate: dateOrNull,
  sortOrder: z.number().int('Use a whole number.').min(0).max(1000).default(0),
  status: z.enum(BANNER_STATUSES).default('active'),
}).superRefine((value, context) => {
  // "No link" and "Offers page" open something fixed, so they have no target.
  const fixedLink = value.ctaType === 'none' || value.ctaType === 'offers'
  if (fixedLink !== (value.ctaTarget === '')) context.addIssue({ code: 'custom', path: ['ctaTarget'], message: fixedLink ? 'Leave this empty: this link has nothing to choose.' : `Choose the ${value.ctaType} this banner opens.` })
  if (value.type === 'warning' && value.imageAssetId) context.addIssue({ code: 'custom', path: ['imageAssetId'], message: 'Warnings are plain text. Remove the picture.' })
  if (value.startDate && value.endDate && value.endDate < value.startDate) context.addIssue({ code: 'custom', path: ['endDate'], message: 'The end date must be on or after the start date.' })
})

export const bannerStatusSchema = z.object({ status: z.enum(BANNER_STATUSES) })
export const idParamsSchema = z.object({ id: z.uuid('That is not a valid banner id.') })

export type BannerInput = z.infer<typeof bannerInputSchema>
export type BannerStatus = (typeof BANNER_STATUSES)[number]
